import React, { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  MessageCircle,
  Send,
  X,
  Shield,
  Bot,
  User
} from "lucide-react";
import { api } from "../utils/api";

/**
 * PremiumChatBot
 * - Floating chatbot (all pages)
 * - Smooth open/close
 * - AI typing animation
 * - Stable state (no 1 sec vanish bug)
 * - Works without login also
 */

export default function PremiumChatBot() {
  const [open, setOpen] = useState(false);
  const [messages, setMessages] = useState([
    {
      role: "bot",
      text:
        "👋 Hi! I’m CyberRaksha AI.\n\nYou can paste a message, link, UPI ID, or phone number. I’ll guide you if it looks SAFE, SUSPICIOUS, or a SCAM."
    }
  ]);

  const [input, setInput] = useState("");
  const [thinking, setThinking] = useState(false);

  const bottomRef = useRef(null);

  // auto scroll
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, thinking]);

  // ===== SEND MESSAGE =====
  async function sendMessage() {
    if (!input.trim() || thinking) return;

    const userMsg = {
      role: "user",
      text: input.trim()
    };

    setMessages((prev) => [...prev, userMsg]);
    setInput("");
    setThinking(true);

    try {
      /**
       * BACKEND ENDPOINT EXPECTED:
       * POST /api/ai/chat
       * { message: string }
       *
       * Response:
       * { reply: string }
       */
      const res = await api.post("/api/ai/chat", {
        message: userMsg.text
      });

      const botReply = {
        role: "bot",
        text:
          res.data?.reply ||
          "⚠️ I couldn’t analyze this properly. Please try again or submit a report."
      };

      setMessages((prev) => [...prev, botReply]);
    } catch (err) {
      setMessages((prev) => [
        ...prev,
        {
          role: "bot",
          text:
            "❌ AI service unavailable right now.\n\n👉 Please use *Scam Check* or try again later."
        }
      ]);
    } finally {
      setThinking(false);
    }
  }

  function onKey(e) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  }

  return (
    <>
      {/* FLOATING BUTTON */}
      <motion.button
        onClick={() => setOpen(true)}
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        className="fixed bottom-6 right-6 z-[9998] flex items-center gap-2 px-5 py-4 rounded-full bg-gray-900 text-white shadow-2xl font-semibold"
      >
        <MessageCircle size={20} />
        Chat
      </motion.button>

      {/* CHAT WINDOW */}
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, y: 20, scale: 0.96 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.96 }}
            transition={{ duration: 0.25 }}
            className="fixed bottom-24 right-6 z-[9999] w-[92vw] max-w-[420px]"
          >
            <div className="rounded-[28px] border border-gray-200 bg-white shadow-2xl overflow-hidden">
              {/* HEADER */}
              <div className="flex items-center justify-between px-5 py-4 bg-gray-900 text-white">
                <div className="flex items-center gap-2 font-black">
                  <Shield size={18} />
                  CyberRaksha AI
                </div>

                <button
                  onClick={() => setOpen(false)}
                  className="p-2 rounded-xl hover:bg-white/10"
                >
                  <X size={18} />
                </button>
              </div>

              {/* MESSAGES */}
              <div className="h-[360px] overflow-auto px-4 py-4 space-y-4 bg-gray-50">
                {messages.map((m, i) => (
                  <div
                    key={i}
                    className={`flex ${
                      m.role === "user" ? "justify-end" : "justify-start"
                    }`}
                  >
                    <div
                      className={`max-w-[85%] rounded-2xl px-4 py-3 text-sm leading-relaxed shadow ${
                        m.role === "user"
                          ? "bg-gray-900 text-white rounded-br-md"
                          : "bg-white border rounded-bl-md"
                      }`}
                    >
                      <div className="flex items-center gap-2 mb-1 text-xs font-bold opacity-70">
                        {m.role === "user" ? (
                          <>
                            <User size={12} /> You
                          </>
                        ) : (
                          <>
                            <Bot size={12} /> AI
                          </>
                        )}
                      </div>
                      <div className="whitespace-pre-wrap">{m.text}</div>
                    </div>
                  </div>
                ))}

                {/* AI TYPING */}
                {thinking && (
                  <div className="flex justify-start">
                    <div className="bg-white border rounded-2xl px-4 py-3 text-sm shadow flex items-center gap-2">
                      <Bot size={14} />
                      <motion.span
                        animate={{ opacity: [0.3, 1, 0.3] }}
                        transition={{
                          duration: 0.9,
                          repeat: Infinity,
                          ease: "easeInOut"
                        }}
                      >
                        AI is analyzing…
                      </motion.span>
                    </div>
                  </div>
                )}

                <div ref={bottomRef} />
              </div>

              {/* INPUT */}
              <div className="border-t bg-white p-3">
                <div className="flex gap-2 items-end">
                  <textarea
                    className="flex-1 resize-none border rounded-2xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-gray-900"
                    placeholder="Paste message, link, UPI ID, number…"
                    rows={2}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={onKey}
                  />

                  <button
                    onClick={sendMessage}
                    disabled={thinking}
                    className="px-4 py-3 rounded-2xl bg-gray-900 text-white disabled:opacity-60"
                  >
                    <Send size={18} />
                  </button>
                </div>

                <div className="text-[11px] text-gray-500 mt-2 text-center">
                  🔒 We never ask for OTP, password, or remote access.
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
